"""Fixed legal text appended by code, never generated by the LLM (ADR-06).

DRAFT: to be validated by a consumer-law professional before any real use (open question D-14).
"""

from __future__ import annotations

from typing import Literal

Lang = Literal["it", "en"]
ClauseKind = Literal["withdrawal", "guarantee"]

CLAUSES: dict[ClauseKind, dict[Lang, str]] = {
    "withdrawal": {
        "it": (
            "Ti ricordiamo che puoi sempre esercitare il diritto di recesso entro 14 giorni "
            "dalla consegna, senza indicarne il motivo. Ti rimborseremo entro 14 giorni dalla "
            "tua comunicazione, al ricevimento dei prodotti o della prova della loro spedizione."
        ),
        "en": (
            "You can always withdraw from your purchase within 14 days of delivery without giving "
            "any reason. We will refund you within 14 days of your notice, once we receive the "
            "items or proof that you have sent them back."
        ),
    },
    "guarantee": {
        "it": (
            "Il prodotto è coperto dalla garanzia legale di conformità: hai diritto alla "
            "riparazione, alla sostituzione o al rimborso senza costi a tuo carico."
        ),
        "en": (
            "The item is covered by the legal guarantee of conformity: you are entitled to a "
            "repair, a replacement or a refund at no cost to you."
        ),
    },
}


def clause(kind: ClauseKind, lang: Lang) -> str:
    return CLAUSES[kind][lang]
